59	/** Books the hour with the least-booked free mentor (lowest id on a tie), or says SLOT_UNAVAILABLE. Never sends email. */
60	export async function bookSlot(
61	  pool: pg.Pool,
62	  input: BookingInput,
63	  now: Date,
64	  hooks?: { beforeInsert?: () => Promise<void> },
65	): Promise<BookResult> {
66	  if (!isBookableTime(input.startsAt, now)) return UNAVAILABLE;
67	
68	  const candidates = (await loadMentors(pool))
69	    .filter((m) => worksAt(m, input.startsAt))
70	    .map((mentor) => ({ mentor, date: localDate(input.startsAt, mentor.timeZone) }));
71	  if (candidates.length === 0) return UNAVAILABLE;
72	
73	  // How loaded each candidate is that day. A stale count only affects the order; the locked check below decides.
74	  const { rows } = await pool.query(
75	    `select mentor_id, mentor_local_date, count(*)::int as n from bookings
76	     where cancelled_at is null and mentor_id = any($1) and mentor_local_date = any($2)
77	     group by mentor_id, mentor_local_date`,
78	    [candidates.map((c) => c.mentor.id), candidates.map((c) => c.date)],
79	  );
80	  const load = new Map<string, number>(rows.map((r) => [`${r.mentor_id}|${r.mentor_local_date}`, r.n]));
81	  const loadOf = (c: (typeof candidates)[number]) => load.get(`${c.mentor.id}|${c.date}`) ?? 0;
82	  candidates.sort((a, b) => loadOf(a) - loadOf(b) || a.mentor.id - b.mentor.id);
83	
84	  for (const { mentor, date } of candidates) {
85	    const client = await pool.connect();
86	    try {
87	      await client.query('begin isolation level read committed');
88	      await client.query('select id from mentors where id = $1 for update', [mentor.id]); // the turnstile: bookings for one mentor take turns (spec §6); relies on read committed
89	      const hour = await client.query('select 1 from bookings where mentor_id = $1 and starts_at = $2 and cancelled_at is null', [mentor.id, input.startsAt]);
90	      if (hour.rowCount) {
91	        await client.query('rollback');
92	        continue;
93	      }
94	      const day = await client.query('select count(*)::int as n from bookings where mentor_id = $1 and mentor_local_date = $2 and cancelled_at is null', [mentor.id, date]);
95	      if (day.rows[0].n >= DAILY_CAP) {
96	        await client.query('rollback');
97	        continue;
98	      }
99	      await hooks?.beforeInsert?.();
100	      const { rows: inserted } = await client.query(
101	        `insert into bookings (mentor_id, starts_at, mentor_local_date, parent_name, parent_email, child_name, parent_time_zone, class_link)
102	         values ($1, $2, $3, $4, $5, $6, $7, $8) returning *`,
103	        [mentor.id, input.startsAt, date, input.parentName, input.parentEmail, input.childName, input.parentTimeZone, newClassLink()],
104	      );
105	      await client.query('commit');
106	      return { ok: true, booking: toBooking(inserted[0]) };
107	    } catch (err) {
108	      await client.query('rollback').catch(() => {}); // a dead connection cannot roll back; keep the first error
109	      if ((err as { code?: string }).code !== '23505') throw err; // 23505: the unique index caught a clash; try the next mentor
110	    } finally {
111	      client.release();
112	    }
113	  }
114	  return UNAVAILABLE;
115	}
