117	export async function getBookingWithMentor(pool: pg.Pool, id: string): Promise<{ booking: Booking; mentor: Mentor } | null> {
118	  const { rows } = await pool.query('select * from bookings where id = $1', [id]);
119	  if (!rows[0]) return null;
120	  const booking = toBooking(rows[0]);
121	  const mentor = (await loadMentors(pool)).find((m) => m.id === booking.mentorId);
122	  return mentor ? { booking, mentor } : null;
123	}
