import { readdir, readFile } from 'node:fs/promises';
import pg from 'pg';

// pg turns a `date` into local midnight, which shifts a day in zones east of UTC. Keep it a plain 'YYYY-MM-DD'.
pg.types.setTypeParser(pg.types.builtins.DATE, (v) => v);

const MIGRATION_LOCK = 727001;

export function createPool(connectionString: string, max?: number): pg.Pool {
  const pool = new pg.Pool({ connectionString, max });
  // pg-pool stops listening for errors on a checked-out client; without this a dropped connection mid-transaction crashes the process.
  // A query in flight already rejects with the error, and any later query on the dead client rejects too, so nothing is lost by ignoring the event.
  pool.on('connect', (client) => client.on('error', () => {}));
  pool.on('error', (err: Error & { code?: string }) => {
    // 57P01: the server ended an idle connection, as a test teardown's `drop database ... with (force)` does.
    if (err.code !== '57P01') console.error('postgres pool error', err);
  });
  return pool;
}

export async function migrate(pool: pg.Pool): Promise<string[]> {
  const dir = new URL('../../migrations/', import.meta.url);
  const client = await pool.connect();
  try {
    await client.query('select pg_advisory_lock($1)', [MIGRATION_LOCK]);
    await client.query(
      'create table if not exists schema_migrations (name text primary key, applied_at timestamptz not null default now())',
    );
    const done = new Set((await client.query('select name from schema_migrations')).rows.map((r) => r.name));
    const applied: string[] = [];
    for (const name of (await readdir(dir)).filter((f) => f.endsWith('.sql')).sort()) {
      if (done.has(name)) continue;
      const sql = await readFile(new URL(name, dir), 'utf8');
      try {
        await client.query('begin');
        await client.query(sql);
        await client.query('insert into schema_migrations (name) values ($1)', [name]);
        await client.query('commit');
      } catch (err) {
        await client.query('rollback');
        throw err;
      }
      applied.push(name);
    }
    return applied;
  } finally {
    try {
      await client.query('select pg_advisory_unlock($1)', [MIGRATION_LOCK]);
    } finally {
      client.release();
    }
  }
}
import { addDays, localDate, weekdayOf, zonedTimeToInstant } from '../shared/time.ts';

export const CLASS_MINUTES = 60, LEAD_MINUTES = 120, HORIZON_DAYS = 14, DAILY_CAP = 2;

const MINUTE_MS = 60_000;
const HOUR_MS = 60 * MINUTE_MS;
const CLASS_MS = CLASS_MINUTES * MINUTE_MS;

export type WorkingHours = { weekday: number; start: string; end: string }; // 'HH:MM', in the mentor's own time zone
export type Mentor = { id: number; name: string; email: string; bio: string; subjects: string[]; timeZone: string; hours: WorkingHours[] };
export type ActiveBooking = { mentorId: number; startsAt: Date; mentorLocalDate: string };
export type Slot = { startsAt: Date; available: boolean };

/** On the UTC hour, and inside [now + 120 minutes, now + 14 days], both ends inclusive. */
export function isBookableTime(startsAt: Date, now: Date): boolean {
  const t = startsAt.getTime();
  return t % HOUR_MS === 0 && t >= now.getTime() + LEAD_MINUTES * MINUTE_MS && t <= now.getTime() + HORIZON_DAYS * 24 * HOUR_MS;
}

/** The mentor's working windows on one of their own calendar days, as [open, close] in epoch ms. */
function windows(mentor: Mentor, date: string): [number, number][] {
  const weekday = weekdayOf(date);
  return mentor.hours
    .filter((h) => h.weekday === weekday)
    .map((h) => [zonedTimeToInstant(date, h.start, mentor.timeZone).getTime(), zonedTimeToInstant(date, h.end, mentor.timeZone).getTime()]);
}

/** True when the whole class fits one working-hours window on the mentor's own day. */
export function worksAt(mentor: Mentor, startsAt: Date): boolean {
  const t = startsAt.getTime();
  return windows(mentor, localDate(startsAt, mentor.timeZone)).some(([open, close]) => t >= open && t + CLASS_MS <= close);
}

/** Class starts on the UTC hour inside [from, to], sorted and unique. */
export function classStarts(mentor: Mentor, from: Date, to: Date): Date[] {
  const starts = new Set<number>();
  // a day either side is purely defensive; walking the mentor's own local dates already covers a UTC-date straddle
  const last = addDays(localDate(to, mentor.timeZone), 1);
  for (let date = addDays(localDate(from, mentor.timeZone), -1); date <= last; date = addDays(date, 1)) {
    for (const [open, close] of windows(mentor, date)) {
      for (let t = Math.ceil(open / HOUR_MS) * HOUR_MS; t + CLASS_MS <= close; t += HOUR_MS) {
        if (t >= from.getTime() && t <= to.getTime()) starts.add(t);
      }
    }
  }
  return [...starts].sort((a, b) => a - b).map((t) => new Date(t));
}

/** Every bookable hour, open or full, sorted by start. An hour is open when any mentor working it is free and under the daily cap. */
export function buildSlots(mentors: Mentor[], bookings: ActiveBooking[], now: Date): Slot[] {
  const taken = new Set(bookings.map((b) => `${b.mentorId}|${b.startsAt.getTime()}`));
  const perDay = new Map<string, number>();
  for (const b of bookings) {
    const key = `${b.mentorId}|${b.mentorLocalDate}`;
    perDay.set(key, (perDay.get(key) ?? 0) + 1);
  }

  const from = new Date(now.getTime() + LEAD_MINUTES * MINUTE_MS);
  const to = new Date(now.getTime() + HORIZON_DAYS * 24 * HOUR_MS);
  const open = new Map<number, boolean>();
  for (const mentor of mentors) {
    for (const start of classStarts(mentor, from, to)) {
      const t = start.getTime();
      const free = !taken.has(`${mentor.id}|${t}`) && (perDay.get(`${mentor.id}|${localDate(start, mentor.timeZone)}`) ?? 0) < DAILY_CAP;
      open.set(t, (open.get(t) ?? false) || free);
    }
  }
  return [...open].sort((a, b) => a[0] - b[0]).map(([t, available]) => ({ startsAt: new Date(t), available }));
}
import { randomBytes } from 'node:crypto';
import type pg from 'pg';
import { expect } from 'vitest';
import { localDate } from '../shared/time.ts';
import { loadMentors } from './bookings.ts';
import { createPool, migrate } from './db.ts';
import { DAILY_CAP, worksAt } from './slots.ts';

export type TestDb = { pool: pg.Pool; drop(): Promise<void> };

const hex = () => randomBytes(6).toString('hex');

// A throwaway, fully migrated database, so every test file runs against its own data.
export async function createTestDb(): Promise<TestDb> {
  const adminUrl = process.env.DATABASE_URL ?? 'postgres://bookings:bookings@localhost:5433/bookings';
  const name = `t_${hex()}`;
  const admin = createPool(adminUrl, 1);
  await admin.query(`create database "${name}"`);
  const url = new URL(adminUrl);
  url.pathname = `/${name}`;
  const pool = createPool(url.toString(), 40); // 40 connections for the race tests
  const drop = async () => {
    await pool.end();
    await admin.query(`drop database "${name}" with (force)`);
    await admin.end();
  };
  try {
    await migrate(pool);
  } catch (err) {
    await drop();
    throw err;
  }
  return { pool, drop };
}

export async function insertMentor(
  pool: pg.Pool,
  m: { name?: string; timeZone: string; hours: { weekday: number; start: string; end: string }[] },
): Promise<number> {
  const { rows } = await pool.query(
    `insert into mentors (name, email, time_zone, bio, subjects) values ($1, $2, $3, 'Test mentor', '{Coding}') returning id`,
    [m.name ?? 'Test Mentor', `m-${hex()}@mentors.example`, m.timeZone],
  );
  const id: number = rows[0].id;
  for (const h of m.hours) {
    await pool.query('insert into mentor_hours (mentor_id, weekday, start_time, end_time) values ($1, $2, $3, $4)', [
      id,
      h.weekday,
      h.start,
      h.end,
    ]);
  }
  return id;
}

// The three promises the database must keep, however the requests interleaved. Tests call this after a burst.
export async function expectBookingRulesHold(pool: pg.Pool): Promise<void> {
  const doubled = await pool.query('select mentor_id, starts_at from bookings where cancelled_at is null group by mentor_id, starts_at having count(*) > 1');
  expect(doubled.rows, 'a mentor booked twice in one hour').toEqual([]);
  const over = await pool.query(
    'select mentor_id, mentor_local_date from bookings where cancelled_at is null group by mentor_id, mentor_local_date having count(*) > $1',
    [DAILY_CAP],
  );
  expect(over.rows, `a mentor over ${DAILY_CAP} classes in one of their own days`).toEqual([]);
  const mentors = new Map((await loadMentors(pool)).map((m) => [m.id, m]));
  const { rows } = await pool.query('select id, mentor_id, starts_at, mentor_local_date from bookings');
  const wrong = rows.filter((r) => {
    const mentor = mentors.get(r.mentor_id)!;
    return !worksAt(mentor, r.starts_at) || r.mentor_local_date !== localDate(r.starts_at, mentor.timeZone);
  });
  expect(wrong, 'a booking outside working hours or with the wrong mentor-local date').toEqual([]);
}
